<?php $h=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); $fcfa=fn($v)=>number_format((float)$v,0,',',' ').' FCFA'; ?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $h($title) ?></title><link href="https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css" rel="stylesheet"></head><body class="bg-gray-100"><main class="max-w-2xl mx-auto p-6"><a class="text-blue-700" href="/suivi-client/ouvrir-saisie">← Brouillons</a><?php if($draft):?><article class="mt-4 bg-white p-6 rounded shadow"><h1 class="text-2xl font-bold">Brouillon <?= $h($draft['numero_brouillon']) ?></h1><dl class="grid grid-cols-2 gap-3 mt-4"><dt>Client</dt><dd><?= $h($draft['nom'].' '.$draft['prenom']) ?></dd><dt>Téléphone</dt><dd><?= $h($draft['telephone']) ?></dd><dt>Date prévue</dt><dd><?= $h($draft['date_mouvement']) ?></dd><dt>Montant</dt><dd><?= $fcfa($draft['montant']) ?></dd><dt>Mode</dt><dd><?= $h($draft['mode_paiement']) ?></dd><dt>Créé par</dt><dd><?= $h(trim(($draft['utilisateur_nom']??'').' '.($draft['utilisateur_prenom']??''))) ?></dd><dt>Observations</dt><dd><?= nl2br($h($draft['notes'])) ?></dd></dl><a class="inline-block mt-5 bg-green-700 text-white p-2 rounded" href="/suivi-client/saisie-reglement?brouillon_id=<?= $draft['id'] ?>">Reprendre</a></article><?php else:?><p class="mt-4 bg-yellow-100 p-3">Brouillon introuvable ou déjà traité.</p><?php endif;?></main></body></html>
